#include <vector>
#include <algorithm>
#include <string>
using namespace std;

class Solution {
public:
    vector<int> sortByReflection(vector<int>& nums) {
        auto reflect = [](int x) -> int {
            string b = "";
            while (x > 0) {
                b += (x & 1) ? '1' : '0';
                x >>= 1;
            }
            int res = 0;
            for (char c : b) {
                res = (res << 1) | (c - '0');
            }
            return res;
        };
        vector<int> res = nums;
        sort(res.begin(), res.end(), [&](int a, int b) {
            int ra = reflect(a), rb = reflect(b);
            if (ra != rb) return ra < rb;
            return a < b;
        });
        return res;
    }
};

import java.util.*;

class Solution {
    private int reflect(int x) {
        String b = Integer.toBinaryString(x);
        String rev = new StringBuilder(b).reverse().toString();
        return Integer.parseInt(rev, 2);
    }

    public int[] sortByReflection(int[] nums) {
        Integer[] arr = Arrays.stream(nums).boxed().toArray(Integer[]::new);
        Arrays.sort(arr, (a, b) -> {
            int ra = reflect(a), rb = reflect(b);
            if (ra != rb) return Integer.compare(ra, rb);
            return Integer.compare(a, b);
        });
        return Arrays.stream(arr).mapToInt(i -> i).toArray();
    }
}

var sortByReflection = function(nums) {
    const reflect = x => parseInt(x.toString(2).split('').reverse().join(''), 2);
    return nums.slice().sort((a, b) => {
        const ra = reflect(a), rb = reflect(b);
        if (ra !== rb) return ra - rb;
        return a - b;
    });
};
